import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int h = sc.nextInt();
        int m = sc.nextInt();
        Clock c = new Clock(h, m);
        System.out.println(c);
    }
}

class Clock {
    int hours;
    int minutes;

    Clock(int h, int m) {
        hours = h + m / 60;
        minutes = m % 60;
        hours = hours % 24;
    }

    public String toString() {
        return String.format("%02d:%02d", hours, minutes);
    }
}

