class Money {
    int amount;

    Money(int amount) {
        this.amount = amount;
    }

    Money(Money other) {
        this.amount = other.amount;
    }

    Money add(Money other) {
        Money result = new Money(this.amount);
        result.amount = result.amount + other.amount;
        return result;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine().trim();
        String[] parts = line.split(" ");
        for (int i = 0; i < parts.length; i++) {
            String cmd = parts[i];
            if (cmd.equals("B")) {
                new ChainLogger();
            } else {
                i++;
                new ChainLogger(parts[i]);
            }
        }
        System.out.println(ChainLogger.trail);
    }
}

class ChainLogger {
    static String trail = "";

    ChainLogger() {
        trail = trail + "B";
    }

    ChainLogger(String tag) {
        this();
        trail = trail + "T";
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Product[] items = new Product[n];
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split(" ");
            if (parts.length == 1) {
                items[i] = new Product(parts[0]);
            } else if (parts.length == 2) {
                items[i] = new Product(parts[0], Integer.parseInt(parts[1]));
            } else {
                items[i] = new Product(parts[0], Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
            }
        }
        for (int i = 0; i < n; i++) {
            items[i].print();
        }
    }
}

class Product {
    String name;
    int price;
    int qty;

    Product(String name) {
        this.name = name;
        this.price = 0;
        this.qty = 0;
    }

    Product(String name, int price) {
        this.name = name;
        this.price = price;
        this.qty = 0;
    }

    Product(String name, int price, int qty) {
        this.name = name;
        this.price = price;
        this.qty = qty;
    }

    void print() {
        System.out.println("Item: " + name + ", Price: " + price + ", Qty: " + qty);
    }
}
